{
  "findings": [
    {
      "check_id": "CKV_AZURE_3",
      "title": "Secure transfer is disabled",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "HIGH",
      "explanation": "The storage account explicitly permits non-HTTPS traffic, allowing data and credentials to be transmitted over unencrypted connections."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                      = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name       = azurerm_resource_group.smart_grid_rg.name\n  location                  = azurerm_resource_group.smart_grid_rg.location\n  account_tier              = \"Standard\"\n  account_replication_type  = \"LRS\"\n  enable_https_traffic_only = true\n}\n",
  "fix_summary": "Enabled HTTPS-only traffic for the Azure Storage account to require encrypted connections."
}
